 * Normalization of parsed URI reference components, and serialization back
 * to text.
 */
import { RecordError } from './errors.js'
import { parseAuthority } from './parse.js'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

const HEX_DIGITS = /^[0-9A-Fa-f]{2}$/
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Uppercases the hex digits of every `%XX` in `text` and decodes the ones
 * that encode an unreserved character. Throws a `RecordError` naming
 * `component` when a `%` is not followed by two hex digits.
 */
function normalizePercentEncoding(text, component) {
  let result = ''
  for (let i = 0; i < text.length; i++) {
    const char = text[i]
    if (char !== '%') {
      result += char
      continue
    }
    const hex = text.slice(i + 1, i + 3)
    if (!HEX_DIGITS.test(hex)) {
      throw new RecordError(`the ${component} has a truncated percent-encoding`)
    }
    const upperHex = hex.toUpperCase()
    const decoded = String.fromCharCode(parseInt(upperHex, 16))
    result += UNRESERVED.test(decoded) ? decoded : `%${upperHex}`
    i += 2
  }
  return result
}

function lowerAscii(text) {
  return text.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

/**
 * Removes dot segments from a path by RFC 3986 section 5.2.4.
 */
export function removeDotSegments(path) {
  let input = path
  const output = []
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const start = input[0] === '/' ? 1 : 0
      let next = input.indexOf('/', start)
      if (next === -1) next = input.length
      output.push(input.slice(0, next))
      input = input.slice(next)
    }
  }
  return output.join('')
}

/**
 * Normalizes parsed components (`scheme`, raw `authority` text or `null`,
 * `path`, `query`, `fragment`) and serializes the result back to text.
 */
export function normalizeComponents({ scheme, authority, path, query, fragment }) {
  const normalizedScheme = scheme !== null ? lowerAscii(scheme) : null

  let normalizedAuthority = null
  if (authority !== null) {
    const { userinfo, host, port } = parseAuthority(authority)

    const normalizedUserinfo = userinfo !== null ? normalizePercentEncoding(userinfo, 'userinfo') : null
    let normalizedHost = lowerAscii(normalizePercentEncoding(host, 'host'))

    let normalizedPort = port
    if (normalizedPort === '') {
      normalizedPort = null
    } else if (normalizedPort !== null && normalizedScheme !== null && DEFAULT_PORTS[normalizedScheme] === normalizedPort) {
      normalizedPort = null
    }

    normalizedAuthority =
      (normalizedUserinfo !== null ? `${normalizedUserinfo}@` : '') +
      normalizedHost +
      (normalizedPort !== null ? `:${normalizedPort}` : '')
  }

  let normalizedPath = removeDotSegments(normalizePercentEncoding(path, 'path'))
  const normalizedQuery = query !== null ? normalizePercentEncoding(query, 'query') : null
  const normalizedFragment = fragment !== null ? normalizePercentEncoding(fragment, 'fragment') : null

  if (normalizedAuthority !== null && normalizedPath === '') {
    normalizedPath = '/'
  }

  let result = ''
  if (normalizedScheme !== null) result += `${normalizedScheme}:`
  if (normalizedAuthority !== null) result += `//${normalizedAuthority}`
  result += normalizedPath
  if (normalizedQuery !== null) result += `?${normalizedQuery}`
  if (normalizedFragment !== null) result += `#${normalizedFragment}`
  return result
}
