 * Uppercases the hex digits of every `%XX` in `text` and decodes the ones
 * that encode an unreserved character. Throws a `RecordError` naming
 * `component` when a `%` is not followed by two hex digits.
 */
function normalizePercentEncoding(text, component) {
  let result = ''
  for (let i = 0; i < text.length; i++) {
    const char = text[i]
    if (char !== '%') {
      result += char
      continue
    }
    const hex = text.slice(i + 1, i + 3)
    if (!HEX_DIGITS.test(hex)) {
      throw new RecordError(`the ${component} has a truncated percent-encoding`)
    }
    const upperHex = hex.toUpperCase()
    const decoded = String.fromCharCode(parseInt(upperHex, 16))
    result += UNRESERVED.test(decoded) ? decoded : `%${upperHex}`
    i += 2
  }
