/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */
import { RecordError } from './errors.js'
import { parseReference } from './parse.js'
import { normalizeComponents } from './normalize.js'
import { resolveReference } from './resolve.js'

function splitRecords(text) {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function processLine(mode, line) {
  if (mode === 'normalize') {
    return normalizeComponents(parseReference(line))
  }

  const spaceIndex = line.indexOf(' ')
  if (spaceIndex === -1) {
    throw new RecordError('expected a base and a reference')
  }
  const base = parseReference(line.slice(0, spaceIndex))
  if (base.scheme === null) {
    throw new RecordError('the base has no scheme')
  }
  const reference = parseReference(line.slice(spaceIndex + 1))
  return normalizeComponents(resolveReference(base, reference))
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = readStdin()
  const records = splitRecords(input)

  const results = []
  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    try {
      results.push(processLine(mode, records[i]))
    } catch (err) {
      if (err instanceof RecordError) {
        process.stderr.write(`error: line ${lineNumber}: ${err.message}\n`)
        process.exit(2)
      }
      throw err
    }
  }

  process.stdout.write(results.map((line) => `${line}\n`).join(''))
}

main()
"}

