import { spawnSync } from 'node:child_process'
function run(mode, input) {
  const r = spawnSync(process.execPath, ['src/cli.js', mode], { encoding: 'utf8', input })
  return { code: r.status, out: r.stdout, err: r.stderr }
}

const cases = [
  ['normalize', 'http://a/b?\n', 'http://a/b?\n'],
  ['normalize', 'http://a/b\n', 'http://a/b\n'],
  ['normalize', 'http:///path\n', 'http:///path\n'],
  ['normalize', '/a/b/../c\n', '/a/c\n'],
  ['normalize', 'http://a:080/x\n', 'http://a:080/x\n'],
  ['normalize', 'http://USER:pass@Example.COM:80/x\n', 'http://USER:pass@example.com/x\n'],
  ['normalize', 'http://a/%2f\n', 'http://a/%2F\n'],
  ['resolve', 'http://a b\n', 'http://a/b\n'],
  ['resolve', 'mailto:x y\n', 'mailto:y\n'],
  ['resolve', 'http://a/b/c/d;p?q .\n', 'http://a/b/c/\n'],
  ['resolve', 'http://a/b/c/d;p?q ..\n', 'http://a/b/\n'],
  ['resolve', 'http://a/b/c/d;p?q ../../g\n', 'http://a/g\n'],
  ['resolve', 'http://a/b/c/d;p?q ../../../g\n', 'http://a/g\n'],
  ['normalize', 'http://a/%\n', null], // truncated
]

for (const [mode, input, expected] of cases) {
  const r = run(mode, input)
  const got = r.code === 0 ? r.out : `ERR(${r.code}): ${r.err}`
  const status = expected === null ? (r.code !== 0 ? 'OK(error)' : 'FAIL(expected error)') : (r.out === expected ? 'OK' : 'FAIL')
  console.log(status, JSON.stringify(input), '=>', JSON.stringify(got), expected !== null ? `expected ${JSON.stringify(expected)}` : '')
}
EOF
","description":"Run manual edge case checks"}

